internal val COUNTRY_NAMES_KN: String =
    "root\u001F01ಅಂಡೋರಾ\u001Eಯುನೈಟೆಡ್ ಅರಬ್ ಎಮಿರೇಟ್ಸ್\u001Eಅಫಘಾನಿಸ್ಥಾನ\u001Eಆಂಟಿಗುವಾ ಮತ್ತು ಬರ್ಬುಡಾ\u001Eಆಂಗ್ವಿಲ್ಲಾ\u001Eಅಲ್ಬೇನಿಯಾ\u001Eಆರ್ಮೇನಿಯ\u001Eಅಂಗೋಲಾ\u001Eಅಂಟಾರ್ಟಿಕಾ\u001Eಅರ್ಜೆಂಟಿನಾ\u001Eಅಮೇರಿಕನ್ ಸಮೋವಾ\u001Eಆಸ್ಟ್ರಿಯಾ\u001Eಆಸ್ಟ್ರೇಲಿಯಾ\u001Eಅರುಬಾ\u001Eಆಲ್ಯಾಂಡ್ ದ್ವೀಪಗಳು\u001Eಅಜರ್ಬೈಜಾನ್\u001Eಬೋಸ್ನಿಯಾ ಮತ್ತು ಹರ್ಜೆಗೋವಿನಾ\u001Eಬಾರ್ಬಡೋಸ್\u001Eಬಾಂಗ್ಲಾದೇಶ\u001Eಬೆಲ್ಜಿಯಮ್\u001Eಬುರ್ಕಿನಾ ಫಾಸೊ\u001Eಬಲ್ಗೇರಿಯಾ\u001Eಬಹ್ರೇನ್\u001Eಬುರುಂಡಿ\u001Eಬೆನಿನ್\u001Eಸೇಂಟ್ ಬಾರ್ಥೆಲೆಮಿ\u001Eಬರ್ಮುಡಾ\u001Eಬ್ರೂನಿ\u001Eಬೊಲಿವಿಯಾ\u001Eಕೆರೀಬಿಯನ್ ನೆದರ್‌ಲ್ಯಾಂಡ್ಸ್\u001Eಬ್ರೆಜಿಲ್\u001Eಬಹಾಮಾಸ್\u001Eಭೂತಾನ್\u001Eಬೋವೆಟ್ ದ್ವೀಪ\u001Eಬೋಟ್ಸ್‌ವಾನಾ\u001Eಬೆಲಾರಸ್\u001Eಬೆಲಿಜ್\u001Eಕೆನಡಾ\u001Eಕೊಕೊಸ್ (ಕೀಲಿಂಗ್) ದ್ವೀಪಗಳು\u001Eಕಾಂಗೋ - ಕಿನ್ಶಾಸಾ\u001Eಮಧ್ಯ ಆಫ್ರಿಕಾ ಗಣರಾಜ್ಯ\u001Eಕಾಂಗೋ - ಬ್ರಾಜಾವಿಲ್ಲೇ\u001Eಸ್ವಿಟ್ಜರ್ಲ್ಯಾಂಡ್\u001Eಕೋತ್ ದ್‘ಇವಾರ್\u001Eಕುಕ್ ದ್ವೀಪಗಳು\u001Eಚಿಲಿ\u001Eಕ್ಯಾಮರೂನ್\u001Eಚೀನಾ\u001Eಕೊಲಂಬಿಯಾ\u001Eಕೊಸ್ಟಾ ರಿಕಾ\u001Eಕ್ಯೂಬಾ\u001Eಕೇಪ್ ವರ್ಡೆ\u001Eಕುರಾಕಾವ್\u001Eಕ್ರಿಸ್ಮಸ್ ದ್ವೀಪ\u001Eಸೈಪ್ರಸ್\u001Eಝೆಕಿಯಾ\u001Eಜರ್ಮನಿ\u001Eಜಿಬೂಟಿ\u001Eಡೆನ್ಮಾರ್ಕ್\u001Eಡೊಮಿನಿಕಾ\u001Eಡೊಮೆನಿಕನ್ ರಿಪಬ್ಲಿಕ್\u001Eಅಲ್ಜೀರಿಯ\u001Eಈಕ್ವೆಡಾರ್\u001Eಎಸ್ಟೋನಿಯಾ\u001Eಈಜಿಪ್ಟ್\u001Eಪಶ್ಚಿಮ ಸಹಾರಾ\u001Eಎರಿಟ್ರಿಯಾ\u001Eಸ್ಪೇನ್\u001Eಇಥಿಯೋಪಿಯಾ\u001Eಫಿನ್‌ಲ್ಯಾಂಡ್\u001Eಫಿಜಿ\u001Eಫಾಕ್‌ಲ್ಯಾಂಡ್ ದ್ವೀಪಗಳು\u001Eಮೈಕ್ರೋನೇಶಿಯಾ\u001Eಫರೋ ದ್ವೀಪಗಳು\u001Eಫ್ರಾನ್ಸ್\u001Eಗೆಬೊನ್\u001Eಯುನೈಟೆಡ್ ಕಿಂಗ್‌ಡಮ್\u001Eಗ್ರೆನೆಡಾ\u001Eಜಾರ್ಜಿಯಾ\u001Eಫ್ರೆಂಚ್ ಗಯಾನಾ\u001Eಗುರ್ನ್‌ಸೆ\u001Eಘಾನಾ\u001Eಗಿಬ್ರಾಲ್ಟರ್\u001Eಗ್ರೀನ್‌ಲ್ಯಾಂಡ್\u001Eಗ್ಯಾಂಬಿಯಾ\u001Eಗಿನಿ\u001Eಗುಡೆಲೋಪ್\u001Eಈಕ್ವೆಟೋರಿಯಲ್ ಗಿನಿ\u001Eಗ್ರೀಸ್\u001Eದಕ್ಷಿಣ ಜಾರ್ಜಿಯಾ ಮತ್ತು ದಕ್ಷಿಣ ಸ್ಯಾಂಡ್‍ವಿಚ್ ದ್ವೀಪಗಳು\u001Eಗ್ವಾಟೆಮಾಲಾ\u001Eಗುವಾಮ್\u001Eಗಿನಿ-ಬಿಸ್ಸಾವ್\u001Eಗಯಾನಾ\u001Eಹಾಂಗ್ ಕಾಂಗ್ ಎಸ್ಎಆರ್ ಚೈನಾ\u001Eಹರ್ಡ್ ಮತ್ತು ಮ್ಯಾಕ್‌ಡೋನಾಲ್ಡ್ ದ್ವೀಪಗಳು\u001Eಹೊಂಡುರಾಸ್\u001Eಕ್ರೊಯೇಷಿಯಾ\u001Eಹೈಟಿ\u001Eಹಂಗೇರಿ\u001Eಇಂಡೋನೇಶಿಯಾ\u001Eಐರ್ಲೆಂಡ್\u001Eಇಸ್ರೇಲ್\u001Eಐಲ್ ಆಫ್ ಮ್ಯಾನ್\u001Eಭಾರತ\u001Eಬ್ರಿಟೀಷ್ ಹಿಂದೂ ಮಹಾಸಾಗರದ ಪ್ರದೇಶ\u001Eಇರಾಕ್\u001Eಇರಾನ್\u001Eಐಸ್‌ಲ್ಯಾಂಡ್\u001Eಇಟಲಿ\u001Eಜೆರ್ಸಿ\u001Eಜಮೈಕಾ\u001Eಜೋರ್ಡಾನ್\u001Eಜಪಾನ್\u001Eಕೀನ್ಯಾ\u001Eಕಿರ್ಗಿಸ್ಥಾನ್\u001Eಕಾಂಬೋಡಿಯಾ\u001Eಕಿರಿಬಾಟಿ\u001Eಕೊಮೊರೊಸ್\u001Eಸೇಂಟ್ ಕಿಟ್ಸ್ ಮತ್ತು ನೆವಿಸ್\u001Eಉತ್ತರ ಕೊರಿಯಾ\u001Eದಕ್ಷಿಣ ಕೊರಿಯಾ\u001Eಕುವೈತ್\u001Eಕೇಮನ್ ದ್ವೀಪಗಳು\u001Eಕಝಾಕಿಸ್ಥಾನ್\u001Eಲಾವೋಸ್\u001Eಲೆಬನಾನ್\u001Eಸೇಂಟ್ ಲೂಸಿಯಾ\u001Eಲಿಚೆನ್‌ಸ್ಟೈನ್\u001Eಶ್ರೀಲಂಕಾ\u001Eಲಿಬೇರಿಯಾ\u001Eಲೆಸೊಥೊ\u001Eಲಿಥುವೇನಿಯಾ\u001Eಲಕ್ಸೆಂಬರ್ಗ್\u001Eಲಾಟ್ವಿಯಾ\u001Eಲಿಬಿಯಾ\u001Eಮೊರಾಕ್ಕೊ\u001Eಮೊನಾಕೊ\u001Eಮೊಲ್ಡೋವಾ\u001Eಮೊಂಟೆನೆಗ್ರೋ\u001Eಸೇಂಟ್ ಮಾರ್ಟಿನ್\u001Eಮಡಗಾಸ್ಕರ್\u001Eಮಾರ್ಷಲ್ ದ್ವೀಪಗಳು\u001Eಉತ್ತರ ಮ್ಯಾಸಿಡೋನಿಯಾ\u001Eಮಾಲಿ\u001Eಮಯನ್ಮಾರ್ (ಬರ್ಮಾ)\u001Eಮಂಗೋಲಿಯಾ\u001Eಮಕಾವು ಎಸ್ಎಆರ್ ಚೈನಾ\u001Eಉತ್ತರ ಮರಿಯಾನಾ ದ್ವೀಪಗಳು\u001Eಮಾರ್ಟಿನಿಕ್\u001Eಮಾರಿಟೇನಿಯಾ\u001Eಮಾಂಟ್‌ಸೆರಟ್\u001Eಮಾಲ್ಟಾ\u001Eಮಾರಿಷಸ್\u001Eಮಾಲ್ಡೀವ್ಸ್\u001Eಮಲಾವಿ\u001Eಮೆಕ್ಸಿಕೊ\u001Eಮಲೇಶಿಯಾ\u001Eಮೊಜಾಂಬಿಕ್\u001Eನಮೀಬಿಯಾ\u001Eನ್ಯೂ ಕ್ಯಾಲಿಡೋನಿಯಾ\u001Eನೈಜರ್\u001Eನಾರ್ಫೋಕ್ ದ್ವೀಪ\u001Eನೈಜೀರಿಯಾ\u001Eನಿಕಾರಾಗುವಾ\u001Eನೆದರ್‌ಲ್ಯಾಂಡ್ಸ್\u001Eನಾರ್ವೆ\u001Eನೇಪಾಳ\u001Eನೌರು\u001Eನಿಯು\u001Eನ್ಯೂಜಿಲೆಂಡ್\u001Eಓಮನ್\u001Eಪನಾಮಾ\u001Eಪೆರು\u001Eಫ್ರೆಂಚ್ ಪಾಲಿನೇಷ್ಯಾ\u001Eಪಪುವಾ ನ್ಯೂಗಿನಿಯಾ\u001Eಫಿಲಿಫೈನ್ಸ್\u001Eಪಾಕಿಸ್ತಾನ\u001Eಪೋಲ್ಯಾಂಡ್\u001Eಸೇಂಟ್ ಪಿಯರ್ ಮತ್ತು ಮಿಕ್ವೆಲನ್\u001Eಪಿಟ್‌ಕೈರ್ನ್ ದ್ವೀಪಗಳು\u001Eಪ್ಯೂರ್ಟೋ ರಿಕೊ\u001Eಪ್ಯಾಲೇಸ್ಟೇನಿಯನ್ ಪ್ರದೇಶಗಳು\u001Eಪೋರ್ಚುಗಲ್\u001Eಪಲಾವು\u001Eಪರಾಗ್ವೇ\u001Eಖತಾರ್\u001Eರಿಯೂನಿಯನ್\u001Eರೊಮೇನಿಯಾ\u001Eಸೆರ್ಬಿಯಾ\u001Eರಷ್ಯಾ\u001Eರುವಾಂಡಾ\u001Eಸೌದಿ ಅರೇಬಿಯಾ\u001Eಸಾಲೊಮನ್ ದ್ವೀಪಗಳು\u001Eಸೀಶೆಲ್ಲೆಸ್\u001Eಸುಡಾನ್\u001Eಸ್ವೀಡನ್\u001Eಸಿಂಗಪುರ್\u001Eಸೇಂಟ್ ಹೆಲೆನಾ\u001Eಸ್ಲೋವೇನಿಯಾ\u001Eಸ್ವಾಲ್ಬಾರ್ಡ್ ಮತ್ತು ಜಾನ್ ಮೆಯನ್\u001Eಸ್ಲೊವಾಕಿಯಾ\u001Eಸಿಯೆರ್ರಾ ಲಿಯೋನ್\u001Eಸ್ಯಾನ್ ಮೆರಿನೋ\u001Eಸೆನೆಗಲ್\u001Eಸೊಮಾಲಿಯಾ\u001Eಸುರಿನಾಮ್\u001Eದಕ್ಷಿಣ ಸುಡಾನ್\u001Eಸಾವೋ ಟೋಮ್ ಮತ್ತು ಪ್ರಿನ್ಸಿಪಿ\u001Eಎಲ್ ಸಾಲ್ವೇಡಾರ್\u001Eಸಿಂಟ್ ಮಾರ್ಟೆನ್\u001Eಸಿರಿಯಾ\u001Eಎಸ್ವಾಟಿನಿ\u001Eಟರ್ಕ್ಸ್ ಮತ್ತು ಕೈಕೋಸ್ ದ್ವೀಪಗಳು\u001Eಚಾದ್\u001Eಫ್ರೆಂಚ್ ದಕ್ಷಿಣ ಪ್ರದೇಶಗಳು\u001Eಟೋಗೋ\u001Eಥೈಲ್ಯಾಂಡ್\u001Eತಜಿಕಿಸ್ತಾನ್\u001Eಟೊಕೆಲಾವ್\u001Eಟಿಮೋರ್ ಲೆಸ್ಟೆ\u001Eತುರ್ಕಮೆನಿಸ್ತಾನ್\u001Eಟುನೀಶಿಯ\u001Eಟೊಂಗಾ\u001Eತುರ್ಕಿಯೆ\u001Eಟ್ರಿನಿಡಾಡ್ ಮತ್ತು ಟೊಬಾಗೊ\u001Eಟುವಾಲು\u001Eತೈವಾನ್\u001Eತಾಂಜೇನಿಯಾ\u001Eಉಕ್ರೈನ್\u001Eಉಗಾಂಡಾ\u001Eಯುಎಸ್‌ ಔಟ್‌ಲೇಯಿಂಗ್ ದ್ವೀಪಗಳು\u001Eಯುನೈಟೆಡ್ ಸ್ಟೇಟ್ಸ್\u001Eಉರುಗ್ವೆ\u001Eಉಜ್ಬೇಕಿಸ್ಥಾನ್\u001Eವ್ಯಾಟಿಕನ್ ಸಿಟಿ\u001Eಸೇಂಟ್. ವಿನ್ಸೆಂಟ್ ಮತ್ತು ಗ್ರೆನೆಡೈನ್ಸ್\u001Eವೆನೆಜುವೆಲಾ\u001Eಬ್ರಿಟಿಷ್ ವರ್ಜಿನ್ ದ್ವೀಪಗಳು\u001Eಯು.ಎಸ್. ವರ್ಜಿನ್ ದ್ವೀಪಗಳು\u001Eವಿಯೆಟ್ನಾಮ್\u001Eವನೌಟು\u001Eವಾಲಿಸ್ ಮತ್ತು ಫುಟುನಾ\u001Eಸಮೋವಾ\u001Eಯೆಮನ್\u001Eಮಯೊಟ್ಟೆ\u001Eದಕ್ಷಿಣ ಆಫ್ರಿಕಾ\u001Eಜಾಂಬಿಯ\u001Eಜಿಂಬಾಬ್ವೆ"

internal val COUNTRY_NAMES_KN_IN: String =
